logic:
// 반환 true = '이 오브젝트 전투를 끝내라'
enemy = 1 - player.info.team            // 0x930. enemy>=2 면 panic_bounds_check(len=2)

// [1216] 목표 게이트 — 몰가드/세르펜의 Hunt 단계만 대상
if (main_objective & 0xFFFE) != 0x0300 { return false }
//   = tag ∈ {0 Morgard, 1 Serpen} && phase == ObjectPhase::Hunt(3)
//   with_battle(byte2) 는 마스크로 지워져 판정에 영향 없음
is_morgard = (main_objective as u8) == 0

// [1220] 전략 게이트
let s = PlayerState::strategy(player, rnd, cache.game.data, cache.game.vtable)  // 24B
if s.object_finish != ObjectFinishStrategy::KillPriority { return false }

// [1178~1182] objective_entity_id_for_main_objective(data, main_objective) — 인라인
let mode = (cache.game.vtable+0x40)(cache.game.data)          // AbstractGame::get_game_mode -> enum2<GameMode>
if mode.discr != 0 /*Moba 아님*/ { return true }
let moba = mode.payload
let list = if is_morgard { moba.jungle_runner.epic.live_list }   // Vec<usize> @0x198
           else          { moba.jungle_runner.serpen.live_list } // Vec<usize> @0x1c8
if list.len == 0 { return true }        // .get(0) == None
let obj_id = list[0]                    // 첫 원소만 본다(.get(0).copied())

// [1224~1225]
let obj = (cache.game.vtable+0x1f0)(cache.game.data, obj_id)   // AbstractGame::get_entity_by_id
if obj == null { return true }

// [1229~1233] 적 팀 챔피언 5칸을 순서대로 (LLVM 이 완전 언롤)
for slot in 0..5 {
    let e = cache.player_champion[enemy][slot]
    if e == null { continue }                                   // iter_champions 의 filter_map
    if !data.blackboard[enemy].is_recent_visible(cache.game.data, cache.game.vtable, player, e) { continue }   // [1231]
    // [1232] is_ignored_well_enemy(version, player, e) — 인라인됨
    if e.team == TeamType::Player(enemy)
       && path_finder::is_enemy_well_danger(version, player, e.x, e.y) { continue }
    if fight_model::can_enemy_hit_objective(e, obj, 25000) { return false }   // [1233] 한 명이라도 걸리면 계속 싸운다
}
return true                              // [1235] 아무도 못 때린다 → 전투 종료

// 요약: return = !(적 챔피언 중에 '최근 목격됨' && '적 우물권 무시대상 아님' && '오브젝트를 25000 이내로 때릴 수 있음' 인 자가 있음)
